// One reminder per person who has used the bot before but has not practised today.
function flat(items) {
  return items.map(function (it) {
    const f = it.json.fields || it.json;
    const out = {};
    for (const k in f) { out[k] = f[k]; }
    return out;
  });
}

const attempts = flat($('Load every attempt').all()).filter(function (a) { return a.chat_id && a.created_at; });
const questions = flat($('Load the question bank').all()).filter(function (q) { return q.question_id && q.text; });

const questionText = {};
questions.forEach(function (q) { questionText[q.question_id] = q.text; });

const now = new Date();
const today = now.toISOString().slice(0, 10);

// Group every attempt by the chat it came from.
const byChat = {};
const chatIds = [];
attempts.forEach(function (a) {
  const id = String(a.chat_id);
  if (!byChat[id]) { byChat[id] = []; chatIds.push(id); }
  byChat[id].push(a);
});

const out = [];

chatIds.forEach(function (id) {
  const rows = byChat[id];

  const days = {};
  rows.forEach(function (r) {
    const t = Date.parse(r.created_at);
    if (!isNaN(t)) { days[new Date(t).toISOString().slice(0, 10)] = true; }
  });

  // Already practised today, so leave them alone.
  if (days[today]) { return; }

  // Streak counts back from yesterday, since today is still empty.
  let streak = 0;
  let cursor = new Date(now.getTime() - 24 * 60 * 60 * 1000);
  for (let i = 0; i < 365; i++) {
    const key = cursor.toISOString().slice(0, 10);
    if (!days[key]) { break; }
    streak += 1;
    cursor = new Date(cursor.getTime() - 24 * 60 * 60 * 1000);
  }

  // Anyone dormant for more than a fortnight gets left in peace.
  let mostRecent = 0;
  rows.forEach(function (r) {
    const t = Date.parse(r.created_at);
    if (!isNaN(t) && t > mostRecent) { mostRecent = t; }
  });
  if (now.getTime() - mostRecent > 14 * 24 * 60 * 60 * 1000) { return; }

  const due = rows.filter(function (r) {
    const d = Date.parse(r.due_at || '');
    return !isNaN(d) && d <= now.getTime();
  });

  const lines = [];

  if (streak > 0) {
    lines.push('You are on a ' + streak + ' day streak. One question keeps it alive.');
  } else {
    lines.push('No practice today. One question is enough to start again.');
  }

  if (due.length > 0) {
    const pick = due[0];
    const text = questionText[pick.question_id];
    if (text) {
      lines.push('');
      lines.push('Due for another go:');
      lines.push(text);
    }
  }

  lines.push('');
  lines.push('Send /practice when you are ready.');

  out.push({ json: { chat_id: id, reply: lines.join('\n') } });
});

return out;
